import "core-js/modules/es.array.push.js";
import { ref, reactive, onMounted } from 'vue';
import { useRouter } from 'vue-router';
import { getUserProfile, editUserProfile } from '@/services/api';
export default {
  setup() {
    const router = useRouter();
    const profileForm = reactive({});
    const formErrors = reactive({});
    const isLoading = ref(false);
    const snackbar = ref(false);
    const snackbarMessage = ref('');
    const snackbarColor = ref('success');
    const formatLabel = key => {
      return key.split('_').map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' ');
    };
    const clearError = field => {
      if (formErrors[field]) {
        formErrors[field] = [];
      }
    };
    const fetchUserDetails = async () => {
      try {
        const response = await getUserProfile();
        Object.keys(response).forEach(key => {
          profileForm[key] = response[key];
          formErrors[key] = [];
        });
      } catch (error) {
        console.error('Error fetching user details:', error);
        showErrorMessage('Failed to fetch user details');
      }
    };
    const saveProfile = async () => {
      isLoading.value = true;
      try {
        const response = await editUserProfile(profileForm);
        // if (response.success) {
        showSuccessMessage('Profile updated successfully');
        setTimeout(() => {
          router.push('/profile');
        }, 1000);
        // } else {
        //   handleErrors(response.errors)
        // }
      } catch (error) {
        console.error('Error saving profile:', error);
        handleErrors(error.errors || {
          general: ['An unexpected error occurred']
        });
      } finally {
        isLoading.value = false;
      }
    };
    const handleErrors = errors => {
      Object.keys(formErrors).forEach(key => {
        formErrors[key] = errors[key] || [];
      });
      if (errors.general) {
        showErrorMessage(errors.general[0]);
      } else {
        showErrorMessage('Failed to update profile. Please check the form for errors.');
      }
    };
    const cancel = () => {
      router.push('/profile');
    };
    const showSuccessMessage = message => {
      snackbarMessage.value = message;
      snackbarColor.value = 'success';
      snackbar.value = true;
    };
    const showErrorMessage = message => {
      snackbarMessage.value = message;
      snackbarColor.value = 'error';
      snackbar.value = true;
    };
    onMounted(fetchUserDetails);
    return {
      profileForm,
      formErrors,
      isLoading,
      snackbar,
      snackbarMessage,
      snackbarColor,
      formatLabel,
      clearError,
      saveProfile,
      cancel
    };
  }
};
